def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        base, _, _ = v.partition('+')

        # Split by '-' to separate pre-release
        parts = base.split('-', 1)
        version_part = parts[0]
        prerelease_part = parts[1] if len(parts) > 1 else None

        # Parse MAJOR.MINOR.PATCH
        version_components = version_part.split('.')
        major = int(version_components[0])
        minor = int(version_components[1]) if len(version_components) > 1 else 0
        patch = int(version_components[2]) if len(version_components) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # A version with a pre-release sorts before the same version without one
        # So we return (has_prerelease, processed_identifiers)
        # has_prerelease: (0, ...) if has pre-release, (1, ...) if no pre-release
        # This ensures versions with pre-release come first

        if not identifiers:
            # No pre-release: sorts after versions with pre-release
            return (1,)

        # Has pre-release: process identifiers
        processed = []
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers compare numerically and sort before other identifiers
                processed.append((0, int(identifier)))
            else:
                # Other identifiers compare by ASCII order
                processed.append((1, identifier))

        # Fewer identifiers sorts first
        return (0, len(processed), tuple(processed))

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_identifiers))

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

